// GPL-3.0-or-later. ESP32 flash is memory mapped; this helper is not an AVR renderer.
#pragma once
#include "transit_font_types.h"
#include <string.h>
inline int32_t transitRoundQ6(int32_t value){return value>=0?(value+32)/64:-((-value+32)/64);}
inline const TransitGlyph* transitGlyph(const TransitFont& font,uint32_t codepoint){size_t low=0,high=font.glyphCount;while(low<high){size_t mid=(low+high)/2;if(font.glyphs[mid].codepoint<codepoint)low=mid+1;else high=mid;}if(low<font.glyphCount&&font.glyphs[low].codepoint==codepoint)return &font.glyphs[low];return nullptr;}
inline int16_t transitKerning(const TransitFont& font,uint32_t left,uint32_t right){const auto* leftGlyph=transitGlyph(font,left);const auto* rightGlyph=transitGlyph(font,right);if(!leftGlyph||!rightGlyph)return 0;const uint16_t li=uint16_t(leftGlyph-font.glyphs),ri=uint16_t(rightGlyph-font.glyphs);size_t low=0,high=font.kerningCount;while(low<high){size_t mid=(low+high)/2;const auto& pair=font.kerning[mid];if(pair.leftIndex<li||(pair.leftIndex==li&&pair.rightIndex<ri))low=mid+1;else high=mid;}if(low<font.kerningCount){const auto& pair=font.kerning[low];if(pair.leftIndex==li&&pair.rightIndex==ri)return pair.adjustmentQ6;}return 0;}
inline uint32_t transitNextCodepoint(const char*& text){const uint8_t first=static_cast<uint8_t>(*text++);if(first<128)return first;uint32_t value;int rest;uint32_t minimum;if((first&0xe0)==0xc0){value=first&31;rest=1;minimum=128;}else if((first&0xf0)==0xe0){value=first&15;rest=2;minimum=2048;}else if((first&0xf8)==0xf0){value=first&7;rest=3;minimum=65536;}else return '?';for(int i=0;i<rest;i++){const uint8_t ch=static_cast<uint8_t>(*text);if(!ch||(ch&0xc0)!=0x80)return '?';++text;value=(value<<6)|(ch&63);}return value<minimum||value>0x10ffff||(value>=0xd800&&value<=0xdfff)?'?':value;}
inline const TransitFont* transitFindFont(const TransitFont* fonts,size_t count,bool bold,int pixels){for(size_t i=0;i<count;i++)if(fonts[i].bold==bold&&fonts[i].pixels==pixels)return &fonts[i];return nullptr;}
inline int32_t transitMeasureQ6(const TransitFont& font,const char* text){int32_t advance=0;uint32_t previous=0;while(*text){uint32_t cp=transitNextCodepoint(text);const auto* glyph=transitGlyph(font,cp);if(!glyph){cp='?';glyph=transitGlyph(font,cp);}if(!glyph)continue;advance+=transitKerning(font,previous,cp)+glyph->advanceQ6;previous=cp;}return advance;}
struct TransitClip {int32_t x,y,width,height;};
// x is the left pen position; baselineY is the font baseline, not the region's top.
// Only black pixels are painted. The caller clears the region to white before drawing.
template<class PixelTarget> void transitDrawText(PixelTarget& target,const TransitFont& font,const char* text,int32_t x,int32_t baselineY,uint16_t color,const TransitClip& clip){int32_t pen=x*64;uint32_t previous=0;while(*text){uint32_t cp=transitNextCodepoint(text);const auto* glyph=transitGlyph(font,cp);if(!glyph){cp='?';glyph=transitGlyph(font,cp);}if(!glyph)continue;pen+=transitKerning(font,previous,cp);const int32_t gx=transitRoundQ6(pen)+glyph->xOffset,gy=baselineY+glyph->yOffset;for(uint32_t i=0;i<uint32_t(glyph->width)*glyph->height;i++){if(!(font.bitmap[glyph->offset+i/8]&(0x80>>(i%8))))continue;const int32_t px=gx+i%glyph->width,py=gy+i/glyph->width;if(px>=clip.x&&py>=clip.y&&px<clip.x+clip.width&&py<clip.y+clip.height)target.drawPixel(px,py,color);}pen+=glyph->advanceQ6;previous=cp;}}
